//! Autogenerated scikit-learn 1.6.1 parity fixtures (numpy 2.0.2) for the
//! ensemble module: ExtraTrees forests (per-tree node arrays) and Bagging
//! meta-estimators (per-estimator sampling indices and predictions). Do not
//! edit by hand. To regenerate, fit the same configurations in sklearn with
//! the seeds below and emit these literals (shortest round-trip decimals).
#![allow(dead_code)]
#![allow(clippy::approx_constant)]

/// One fitted tree inside an ExtraTrees forest fixture.
pub struct EtTreeFixture {
    /// Per-node split feature (-2 = leaf).
    pub features: &'static [i32],
    pub thresholds: &'static [f64],
    pub impurities: &'static [f64],
    pub n_node: &'static [usize],
    /// Classification: flattened n_nodes x n_classes normalized proportions.
    /// Regression: per-node target mean.
    pub values: &'static [f64],
}

/// ExtraTreesClassifier fixture from a seeded sklearn run.
pub struct EtClfFixture {
    pub name: &'static str,
    pub seed: u64,
    pub n_estimators: usize,
    pub criterion: &'static str,
    /// 0 = None (unlimited).
    pub max_depth: usize,
    /// "sqrt", "all", or a decimal count (e.g. "2").
    pub max_features: &'static str,
    pub bootstrap: bool,
    pub min_samples_leaf: usize,
    pub x: &'static [f64],
    pub rows: usize,
    pub cols: usize,
    pub y: &'static [f64],
    pub n_classes: usize,
    /// Empty when only forest-level outputs are pinned (n_estimators=100).
    pub trees: &'static [EtTreeFixture],
    /// Per-tree bootstrap indices (empty when bootstrap=false).
    pub est_samples: &'static [&'static [usize]],
    pub preds: &'static [f64],
    pub proba: &'static [f64],
    pub importances: &'static [f64],
}

/// ExtraTreesRegressor fixture from a seeded sklearn run.
pub struct EtRegFixture {
    pub name: &'static str,
    pub seed: u64,
    pub n_estimators: usize,
    pub max_depth: usize,
    pub max_features: &'static str,
    pub bootstrap: bool,
    pub min_samples_leaf: usize,
    pub x: &'static [f64],
    pub rows: usize,
    pub cols: usize,
    pub y: &'static [f64],
    pub trees: &'static [EtTreeFixture],
    pub est_samples: &'static [&'static [usize]],
    pub preds: &'static [f64],
    pub importances: &'static [f64],
}

/// BaggingClassifier fixture (base: DecisionTreeClassifier, random_state=0).
pub struct BagClfFixture {
    pub name: &'static str,
    pub seed: u64,
    pub n_estimators: usize,
    pub bootstrap: bool,
    pub bootstrap_features: bool,
    /// Integer literal = int path; decimal literal = fraction path.
    pub max_samples: &'static str,
    pub max_features: &'static str,
    /// Base tree max_depth; 0 = None.
    pub base_max_depth: usize,
    pub x: &'static [f64],
    pub rows: usize,
    pub cols: usize,
    pub y: &'static [f64],
    pub n_classes: usize,
    /// Per-estimator predictions on X[:, est_features[i]].
    pub est_preds: &'static [&'static [f64]],
    pub est_samples: &'static [&'static [usize]],
    pub est_features: &'static [&'static [usize]],
    pub preds: &'static [f64],
    pub proba: &'static [f64],
}

/// BaggingRegressor fixture (base: DecisionTreeRegressor, random_state=0).
pub struct BagRegFixture {
    pub name: &'static str,
    pub seed: u64,
    pub n_estimators: usize,
    pub bootstrap: bool,
    pub bootstrap_features: bool,
    pub max_samples: &'static str,
    pub max_features: &'static str,
    pub base_max_depth: usize,
    pub x: &'static [f64],
    pub rows: usize,
    pub cols: usize,
    pub y: &'static [f64],
    pub est_preds: &'static [&'static [f64]],
    pub est_samples: &'static [&'static [usize]],
    pub est_features: &'static [&'static [usize]],
    pub preds: &'static [f64],
}

